<table class="table"><thead><tr><th>User</th><th>Status</th><th>Hosted</th><th>Joined</th><th>Ratings</th><th>Last login</th><th>Actions</th></tr></thead><tbody><?php foreach($users as$u):$uDisabled=$u['status']==='DISABLED';?><tr<?=$uDisabled?' class="user-disabled"':''?>><td><b><a href="?view=user&user=<?=(int)$u['user_id']?>"><?=e($u['display_name'])?></a></b><br><?=e($u['email'])?><?=((int)$u['is_admin']===1)?'<br><span class="muted">Administrator</span>':''?><?=((int)($u['is_writer']??0)===1)?'<br><span class="muted">Story Writer</span>':''?></td><td><?=e($u['status'])?></td><td><?=(int)$u['hosted_count']?></td><td><?=(int)$u['joined_count']?></td><td><?=(int)$u['rating_count']?><?=isset($u['average_rating'])&&$u['average_rating']!==null?' · '.e($u['average_rating']).'/5':''?></td><td><?=e($u['last_login_at_utc']??'Never')?></td><td class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="reset_user"><input type="hidden" name="user_id" value="<?=(int)$u['user_id']?>"><button class="btn alt"<?=$uDisabled?' disabled':''?>>Send reset</button></form> <?php if((int)$u['user_id']!==(int)$admin['user_id']):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle_status"><input type="hidden" name="user_id" value="<?=(int)$u['user_id']?>"><button class="btn alt"><?=$u['status']==='ACTIVE'?'Disable':'Enable'?></button></form> <form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle_admin"><input type="hidden" name="user_id" value="<?=(int)$u['user_id']?>"><button class="btn alt"<?=$uDisabled?' disabled':''?>><?=(int)$u['is_admin']===1?'Remove admin':'Make admin'?></button></form><?php endif;?> <form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle_writer"><input type="hidden" name="user_id" value="<?=(int)$u['user_id']?>"><button class="btn alt"<?=$uDisabled?' disabled':''?>><?=(int)($u['is_writer']??0)===1?'Remove writer':'Make writer'?></butt